        /// <summary>
    /// 2~65 进制的转换。
    /// </summary>
        public static string RadixConvert(string Input, int FromRadix, int ToRadix)
        {
            const string Digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz/+=";
            // 零与负数的处理
            if (string.IsNullOrEmpty(Input))
                return "0";
            bool IsNegative = Input.StartsWithF("-");
            if (IsNegative)
                Input = Input.TrimStart('-');
            // 转换为十进制
            long RealNum = 0L;
            long Scale = 1L;
            foreach (var Digit in Input.Reverse().Select(l => Digits.IndexOfF(Conversions.ToString(l))))
            {
                RealNum += Digit * Scale;
                Scale *= FromRadix;
            }
            // 转换为指定进制
            string Result = "";
            while (RealNum > 0L)
            {
                int NewNum = (int)(RealNum % ToRadix);
                RealNum = (long)Math.Round((RealNum - NewNum) / (double)ToRadix);
                Result = Digits[NewNum] + Result;
            }
            // 负数的结束处理与返回
            return (IsNegative ? "-" : "") + Result;
        }

        /// <summary>
    /// 计算二阶贝塞尔曲线。
    /// </summary>
        public static double MathBezier(double x, double x1, double y1, double x2, double y2, double acc = 0.01d)
        {
            if (x <= 0d || double.IsNaN(x))
                return 0d;
            if (x >= 1d)
                return 1d;
            object a, b;
            a = x;
            do
            {
                b = Operators.MultiplyObject(Operators.MultiplyObject(3, a), Operators.AddObject(Operators.AddObject(Operators.MultiplyObject(Operators.MultiplyObject(0.33333333d + x1 - x2, a), a), Operators.MultiplyObject(x2 - 2d * x1, a)), x1));
                a = Operators.AddObject(a, Operators.MultiplyObject(Operators.SubtractObject(x, b), 0.5d));
            }
            while (!Operators.ConditionalCompareObjectLess(Math.Abs((double)Operators.SubtractObject(b, x)), acc, false)); // 精度
            return Conversions.ToDouble(Operators.MultiplyObject(Operators.MultiplyObject(3, a), Operators.AddObject(Operators.AddObject(Operators.MultiplyObject(Operators.MultiplyObject(0.33333333d + y1 - y2, a), a), Operators.MultiplyObject(y2 - 2d * y1, a)), y1)));
        }

        /// <summary>
    /// 将一个数字限制为 0~255 的 Byte 值。
