        }

        /// <summary>
    /// 符号函数。
    /// </summary>
        public static int MathSgn(double Value)
        {
            if (Value == 0d)
            {
                return 0;
            }
            else if (Value > 0d)
            {
                return 1;
            }
            else
            {
                return -1;
            }
        }

