        /// <summary>
    /// 重命名一个注册表子键。不可用于包含子键的子键。
    /// </summary>
        public static void RenameReg(Microsoft.Win32.RegistryKey parentKey, string subKeyName, string newSubKeyName)
        {
            if (parentKey.GetSubKeyNames().Contains(newSubKeyName))
                parentKey.DeleteSubKeyTree(newSubKeyName, false);
            var SourceKey = parentKey.OpenSubKey(subKeyName);
            if (SourceKey == null)
                return; // 没有目标项
            var NewKey = parentKey.CreateSubKey(newSubKeyName);
            if (SourceKey.GetSubKeyNames().Length > 0)
                throw new NotSupportedException("不支持对包含子键的子键进行重命名：" + SourceKey.GetSubKeyNames()[0] + "。");
            foreach (string valueName in SourceKey.GetValueNames())
            {
                var objValue = SourceKey.GetValue(valueName);
                var valKind = SourceKey.GetValueKind(valueName);
                NewKey.SetValue(valueName, objValue, valKind);
            }
            parentKey.DeleteSubKeyTree(subKeyName, false);
        }
        /// <summary>
    /// 读取注册表，默认为程序所属。
    /// </summary>
        public static string ReadReg(string Key, string DefaultValue = "", string Path = "")
        {
            string ReadRegRet = default;
            try
            {
                Microsoft.Win32.RegistryKey parentKey;
                Microsoft.Win32.RegistryKey softKey;
                parentKey = My.MyWpfExtension.Computer.Registry.CurrentUser;
                softKey = parentKey.OpenSubKey(@"Software\" + (string.IsNullOrEmpty(Path) ? ModSecret.RegFolder : Path), true);
                if (softKey is null)
                {
                    ReadRegRet = DefaultValue; // 不存在则返回默认值
                }
                else
                {
                    var readValue = new StringBuilder();
                    readValue.AppendLine(Conversions.ToString(softKey.GetValue(Key)));
                    string value = readValue.ToString().Replace(Constants.vbCrLf, ""); // 去除莫名的回车
                    return string.IsNullOrEmpty(value) ? DefaultValue : value;
                } // 错误则返回默认值
            }
            catch (Exception ex)
            {
                Log(ex, "读取注册表出错：" + Key, LogLevel.Hint);
                return DefaultValue;
            }

            return ReadRegRet;
        }
        /// <summary>
    /// 写入注册表，默认为程序所属。
    /// </summary>
        public static void WriteReg(string Key, string Value, bool ShowException = false, string Path = "", bool ThrowException = false)
        {
            try
            {
                Microsoft.Win32.RegistryKey parentKey;
                Microsoft.Win32.RegistryKey softKey;
                parentKey = My.MyWpfExtension.Computer.Registry.CurrentUser;
                softKey = parentKey.OpenSubKey(@"Software\" + (string.IsNullOrEmpty(Path) ? ModSecret.RegFolder : Path), true);
                if (softKey is null)
                    softKey = parentKey.CreateSubKey(@"Software\" + (string.IsNullOrEmpty(Path) ? ModSecret.RegFolder : Path)); // 如果不存在就创建  
                softKey.SetValue(Key, Value);
            }
            catch (Exception ex)
            {
                Log(ex, "写入注册表出错：" + Key, ThrowException ? LogLevel.Hint : LogLevel.Developer);
                if (ThrowException)
                    throw;
            }
        }
        /// <summary>
    /// 是否存在某个注册表键。
    /// </summary>
        public static bool HasReg(string Key)
        {
            return ReadReg(Key, null) is not null;
        }
        /// <summary>
    /// 删除注册表键。
    /// </summary>
        public static void DeleteReg(string Key, bool ThrowException = false)
        {
            try
            {
                var SubKey = My.MyWpfExtension.Computer.Registry.CurrentUser.OpenSubKey(@"Software\" + ModSecret.RegFolder, true);
                SubKey?.DeleteValue(Key);
            }
            catch (Exception ex)
            {
                Log(ex, "删除注册表出错：" + Key, ThrowException ? LogLevel.Hint : LogLevel.Developer);
                if (ThrowException)
                    throw;
            }
        }

