        /// <summary>
    /// 将流写入文件。
    /// </summary>
    /// <param name="FilePath">文件完整或相对路径。</param>
        public static bool WriteFile(string FilePath, Stream Stream)
        {
            try
            {
                // 还原文件路径
                if (!FilePath.Contains(@":\"))
                    FilePath = Path + FilePath;
                // 确保目录存在
                Directory.CreateDirectory(GetPathFromFullPath(FilePath));
                // 读取流
                using (var fs = new FileStream(FilePath, FileMode.Create, FileAccess.Write))
                {
                    byte[] srcBuf = new byte[16385];
                    int DataCount = Stream.Read(srcBuf, 0, 16384);
                    while (DataCount > 0)
                    {
                        if (DataCount > 0)
                            fs.Write(srcBuf, 0, DataCount);
                        DataCount = Stream.Read(srcBuf, 0, 16384);
                    }
                    fs.Close();
                }
                return true;
            }
            catch (Exception ex)
            {
                Log(ex, "保存流出错");
                return false;
            }
        }

        // 文件编码
        /// <summary>
    /// 根据字节数组分析其编码。
    /// </summary>
        public static Encoding GetEncoding(byte[] Bytes)
        {
            int Length = Bytes.Count();
            if (Length < 3)
                return new UTF8Encoding(false); // 不带 BOM 的 UTF8
                                                // 根据 BOM 判断编码
            if (Bytes[0] >= 0xEF)
            {
                // 有 BOM 类型
                if (Bytes[0] == 0xEF && Bytes[1] == 0xBB)
                {
                    return new UTF8Encoding(true); // 带 BOM 的 UTF8
                }
                else if (Bytes[0] == 0xFE && Bytes[1] == 0xFF)
                {
                    return Encoding.BigEndianUnicode;
                }
                else if (Bytes[0] == 0xFF && Bytes[1] == 0xFE)
                {
                    return Encoding.Unicode;
                }
                else
                {
                    return Encoding.GetEncoding("GB18030");
                }
            }
            // 无 BOM 文件：GB18030（ANSI）或 UTF8
            string UTF8 = Encoding.UTF8.GetString(Bytes);
            char ErrorChar = Encoding.UTF8.GetString(new[] { (byte)239, (byte)191, (byte)189 }).ToCharArray()[0];
            if (UTF8.Contains(Conversions.ToString(ErrorChar)))
            {
                return Encoding.GetEncoding("GB18030");
            }
            else
            {
                return new UTF8Encoding(false);
            } // 不带 BOM 的 UTF8
        }
        /// <summary>
    /// 解码 Bytes。
    /// </summary>
        public static string DecodeBytes(byte[] Bytes)
        {
            int Length = Bytes.Length;
            if (Length < 3)
                return Encoding.UTF8.GetString(Bytes);
            // 根据 BOM 判断编码
            if (Bytes[0] >= 0xEF)
            {
                // 有 BOM 类型
                if (Bytes[0] == 0xEF && Bytes[1] == 0xBB)
                {
                    return Encoding.UTF8.GetString(Bytes, 3, Length - 3);
                }
                else if (Bytes[0] == 0xFE && Bytes[1] == 0xFF)
                {
                    return Encoding.BigEndianUnicode.GetString(Bytes, 3, Length - 3);
                }
                else if (Bytes[0] == 0xFF && Bytes[1] == 0xFE)
                {
                    return Encoding.Unicode.GetString(Bytes, 3, Length - 3);
                }
                else
                {
                    return Encoding.GetEncoding("GB18030").GetString(Bytes, 3, Length - 3);
                }
            }
            // 无 BOM 文件：GB18030（ANSI）或 UTF8
            string UTF8 = Encoding.UTF8.GetString(Bytes);
            char ErrorChar = Encoding.UTF8.GetString(new[] { (byte)239, (byte)191, (byte)189 }).ToCharArray()[0];
            if (UTF8.Contains(Conversions.ToString(ErrorChar)))
            {
                return Encoding.GetEncoding("GB18030").GetString(Bytes);
            }
            else
            {
                return UTF8;
            }
        }

