        /// <summary>
    /// 文件的校验规则。
    /// </summary>
        public class FileChecker
        {
            /// <summary>
        /// 文件的准确大小。
        /// </summary>
            public long ActualSize = -1;
            /// <summary>
        /// 文件的最小大小。
        /// </summary>
            public long MinSize = -1;
            /// <summary>
        /// 文件的 MD5、SHA1 或 SHA256。会根据输入字符串的长度自动判断种类。
        /// </summary>
            public string Hash = null;
            /// <summary>
        /// 是否可以使用已经存在的文件。
        /// </summary>
            public bool CanUseExistsFile = true;
            /// <summary>
        /// 是否为 Json 文件。
        /// </summary>
            public bool IsJson = false;
            public FileChecker(long MinSize = -1, long ActualSize = -1, string Hash = null, bool CanUseExistsFile = true, bool IsJson = false)
            {
                this.ActualSize = ActualSize;
                this.MinSize = MinSize;
                this.Hash = Hash;
                this.CanUseExistsFile = CanUseExistsFile;
                this.IsJson = IsJson;
            }
            /// <summary>
        /// 检查文件。若成功则返回 Nothing，失败则返回错误的描述文本，描述文本不以句号结尾。不会抛出错误。
        /// </summary>
            public string Check(string LocalPath)
            {
                try
                {
                    var Info = new FileInfo(LocalPath);
                    if (!Info.Exists)
                        return "文件不存在：" + LocalPath;
                    long FileSize = Info.Length;
                    if (ActualSize >= 0L && ActualSize != FileSize)
                    {
                        return $"文件大小应为 {ActualSize} B，实际为 {FileSize} B" + (FileSize < 2000L ? "，内容为：" + ReadFile(LocalPath) : "");
                    }
                    if (MinSize >= 0L && MinSize > FileSize)
                    {
                        return $"文件大小应大于 {MinSize} B，实际为 {FileSize} B" + (FileSize < 2000L ? "，内容为：" + ReadFile(LocalPath) : "");
                    }
                    if (!string.IsNullOrEmpty(Hash))
                    {
                        if (Hash.Length < 35) // MD5
                        {
                            if ((Hash.ToLowerInvariant() ?? "") != (GetFileMD5(LocalPath) ?? ""))
                                return "文件 MD5 应为 " + Hash + "，实际为 " + GetFileMD5(LocalPath);
                        }
                        else if (Hash.Length == 64) // SHA256
                        {
                            if ((Hash.ToLowerInvariant() ?? "") != (GetFileSHA256(LocalPath) ?? ""))
                                return "文件 SHA256 应为 " + Hash + "，实际为 " + GetFileSHA256(LocalPath);
                        }
                        else if ((Hash.ToLowerInvariant() ?? "") != (GetFileSHA1(LocalPath) ?? "")) // SHA1 (40)
                            return "文件 SHA1 应为 " + Hash + "，实际为 " + GetFileSHA1(LocalPath);
                    }
                    if (IsJson)
                    {
                        string Content = ReadFile(LocalPath);
                        if (string.IsNullOrEmpty(Content))
                            throw new Exception("读取到的文件为空");
                        try
                        {
                            GetJson(Content);
                        }
                        catch (Exception ex)
                        {
                            throw new Exception("不是有效的 Json 文件", ex);
                        }
                    }
                    return null;
                }
                catch (Exception ex)
                {
                    Log(ex, "检查文件出错");
                    return GetExceptionSummary(ex);
                }
            }
        }

        /// <summary>
    /// 尝试根据后缀名判断文件种类并解压文件，支持 gz 与 zip，会尝试将 Jar 以 zip 方式解压。
    /// 会尝试创建，但不会清空目标文件夹。
    /// </summary>
        public static void ExtractFile(string CompressFilePath, string DestDirectory, Encoding Encode = null, Action<double> ProgressIncrementHandler = null)
        {
            Directory.CreateDirectory(DestDirectory);
            if (CompressFilePath.EndsWithF(".gz", true))
            {
                // 以 gz 方式解压
                var stream = new GZipStream(new FileStream(CompressFilePath, FileMode.Open, FileAccess.ReadWrite), CompressionMode.Decompress);
                var decompressedFile = new FileStream(DestDirectory + GetFileNameFromPath(CompressFilePath).ToLower().Replace(".tar", "").Replace(".gz", ""), FileMode.OpenOrCreate, FileAccess.Write);
                int data = stream.ReadByte();
                while (data != -1)
                {
                    decompressedFile.WriteByte((byte)data);
                    data = stream.ReadByte();
                }
                decompressedFile.Close();
                stream.Close();
            }
            else
            {
                // 以 zip 方式解压
                using (var Archive = ZipFile.Open(CompressFilePath, ZipArchiveMode.Read, Encode ?? Encoding.GetEncoding("GB18030")))
                {
                    int TotalCount = Archive.Entries.Count;
                    foreach (ZipArchiveEntry Entry in Archive.Entries)
                    {
                        if (ProgressIncrementHandler is not null)
                            ProgressIncrementHandler(1d / TotalCount);
                        string DestinationPath = System.IO.Path.Combine(DestDirectory, Entry.FullName);
                        if (DestinationPath.EndsWithF(@"\") || DestinationPath.EndsWithF("/"))
                        {
                            continue; // 不创建空文件夹
                        }
                        else
                        {
                            Directory.CreateDirectory(GetPathFromFullPath(DestinationPath));
                            Entry.ExtractToFile(DestinationPath, true);
                        }
                    }
                }
            }
        }

        /// <summary>
    /// 删除文件夹，返回删除的文件个数。通过参数选择是否抛出异常。
    /// </summary>
        public static int DeleteDirectory(string Path, bool IgnoreIssue = false)
        {
            if (!Directory.Exists(Path))
                return 0;
            int DeletedCount = 0;
            string[] Files;
            try
            {
                Files = Directory.GetFiles(Path);
            }
            catch (DirectoryNotFoundException ex) // #4549
            {
                Log(ex, $"疑似为孤立符号链接，尝试直接删除（{Path}）", LogLevel.Developer);
                Directory.Delete(Path);
                return 0;
            }
            foreach (string FilePath in Files)
            {
                bool RetriedFile = false;
            RetryFile:
                ;

                try
                {
                    File.Delete(FilePath);
                    DeletedCount += 1;
                }
                catch (Exception ex)
                {
                    if (!RetriedFile)
                    {
                        RetriedFile = true;
                        Log(ex, $"删除文件失败，将在 0.3s 后重试（{FilePath}）");
                        Thread.Sleep(300);
                        goto RetryFile;
                    }
                    else if (IgnoreIssue)
                    {
                        Log(ex, "删除单个文件可忽略地失败");
                    }
                    else
                    {
                        throw;
                    }
                }
            }
            foreach (string str in Directory.GetDirectories(Path))
                DeleteDirectory(str, IgnoreIssue);
            bool RetriedDir = false;
        RetryDir:
            ;

            try
            {
                Directory.Delete(Path, true);
            }
            catch (Exception ex)
            {
                if (!RetriedDir)
                {
                    RetriedDir = true;
                    Log(ex, $"删除文件夹失败，将在 0.3s 后重试（{Path}）");
                    Thread.Sleep(300);
                    goto RetryDir;
                }
                else if (IgnoreIssue)
                {
                    Log(ex, "删除单个文件夹可忽略地失败");
                }
                else
                {
                    throw;
                }
            }
            return DeletedCount;
        }
        /// <summary>
    /// 复制文件夹，失败会抛出异常。
    /// </summary>
        public static void CopyDirectory(string FromPath, string ToPath, Action<double> ProgressIncrementHandler = null)
        {
            FromPath = FromPath.Replace("/", @"\");
            if (!FromPath.EndsWithF(@"\"))
                FromPath += @"\";
            ToPath = ToPath.Replace("/", @"\");
            if (!ToPath.EndsWithF(@"\"))
                ToPath += @"\";
            var AllFiles = EnumerateFiles(FromPath).ToList();
            int FileCount = AllFiles.Count;
            foreach (var File in AllFiles)
            {
                CopyFile(File.FullName, File.FullName.Replace(FromPath, ToPath));
                if (ProgressIncrementHandler is not null)
                    ProgressIncrementHandler(1d / FileCount);
            }
        }
        /// <summary>
    /// 遍历文件夹中的所有文件。
    /// </summary>
        public static IEnumerable<FileInfo> EnumerateFiles(string Directory)
        {
            var Info = new DirectoryInfo(ShortenPath(Directory));
            if (!Info.Exists)
                return new List<FileInfo>();
            return Info.EnumerateFiles("*", SearchOption.AllDirectories);
        }

        /// <summary>
    /// 若路径长度大于指定值，则将长路径转换为短路径。
    /// </summary>
        public static string ShortenPath(string LongPath, int ShortenThreshold = 247)
        {
            if (LongPath.Length <= ShortenThreshold)
                return LongPath;
            var ShortPath = new StringBuilder(260);
            ModBase.GetShortPathName(LongPath, ShortPath, 260);
            return ShortPath.ToString();
        }
        [DllImport("kernel32", EntryPoint = "GetShortPathNameA")]
        private static extern int GetShortPathName(string lpszLongPath, StringBuilder lpszShortPath, int cchBuffer);

