        /// <summary>
    /// 提取 Exception 的具体描述与堆栈。
    /// </summary>
    /// <param name="ShowAllStacks">是否必须显示所有堆栈。通常用于判定堆栈信息。</param>
        public static string GetExceptionDetail(Exception Ex, bool ShowAllStacks = false)
        {
            if (Ex is null)
                return "无可用错误信息！";

            // 获取最底层的异常
            var InnerEx = Ex;
            while (!(InnerEx.InnerException is null))
                InnerEx = InnerEx.InnerException;

            // 获取各级错误的描述与堆栈信息
            var DescList = new List<string>();
            bool IsInner = false;
            while (!(Ex is null))
            {
                DescList.Add((IsInner ? "→ " : "") + Ex.Message.Replace(Constants.vbLf, Constants.vbCr).Replace(Constants.vbCr + Constants.vbCr, Constants.vbCr).Replace(Constants.vbCr, Constants.vbCrLf));
                if (Ex.StackTrace is not null)
                {
                    foreach (string Stack in Ex.StackTrace.Split(Constants.vbCrLf.ToCharArray(), StringSplitOptions.RemoveEmptyEntries))
                    {
                        if (ShowAllStacks || Stack.ContainsF("pcl", true))
                        {
                            DescList.Add(Stack.Replace(Constants.vbCr, string.Empty).Replace(Constants.vbLf, string.Empty));
                        }
                    }
                }
                if (Ex.GetType().FullName != "System.Exception")
                    DescList.Add("   错误类型：" + Ex.GetType().FullName);
                Ex = Ex.InnerException;
                IsInner = true;
            }

            // 常见错误（记得同时修改下面的）
            string CommonReason = null;
            if (InnerEx is TypeLoadException || InnerEx is BadImageFormatException || InnerEx is MissingMethodException || InnerEx is NotImplementedException || InnerEx is TypeInitializationException)
            {
                CommonReason = "PCL 的运行环境存在问题。请尝试重新安装 .NET Framework 4.8 然后再试。若无法安装，请先卸载较新版本的 .NET Framework，然后再尝试安装。";
            }
            else if (InnerEx is UnauthorizedAccessException)
            {
                CommonReason = "PCL 的权限不足。请尝试右键 PCL，选择以管理员身份运行。";
            }
            else if (InnerEx is OutOfMemoryException)
            {
                CommonReason = "你的电脑运行内存不足，导致 PCL 无法继续运行。请在关闭一部分不需要的程序后再试。";
            }
            else if (InnerEx is COMException)
            {
                CommonReason = "由于操作系统或显卡存在问题，导致出现错误。请尝试重启 PCL。";
            }
            else if (new[] { "远程主机强迫关闭了", "远程方已关闭传输流", "未能解析此远程名称", "由于目标计算机积极拒绝", "操作已超时", "操作超时", "服务器超时", "连接超时" }.Any(s => DescList.Any(l => l.Contains(s))))
            {
                CommonReason = "你的网络环境不佳，导致难以连接到服务器。请检查网络，多重试几次，或尝试使用 VPN。";
            }
            else if (InnerEx is PlatformNotSupportedException)
            {
                CommonReason = "你当前的 Windows 版本过低，无法运行当前版本的 PCL。请升级到 Windows 10 或更高版本后再试。";
            }

            // 构造输出信息
            if (CommonReason is null)
            {
                return DescList.Join(Constants.vbCrLf);
            }
            else
            {
                return CommonReason + Constants.vbCrLf + Constants.vbCrLf + "————————————" + Constants.vbCrLf + "详细错误信息：" + Constants.vbCrLf + DescList.Join(Constants.vbCrLf);
            }
        }
        /// <summary>
    /// 提取 Exception 描述，汇总到一行。
