                CommonReason = "PCL 的运行环境存在问题。请尝试重新安装 .NET Framework 4.8 然后再试。若无法安装，请先卸载较新版本的 .NET Framework，然后再尝试安装。";
            }
            else if (InnerEx is UnauthorizedAccessException)
            {
                CommonReason = "PCL 的权限不足。请尝试右键 PCL，选择以管理员身份运行。";
            }
            else if (InnerEx is OutOfMemoryException)
            {
                CommonReason = "你的电脑运行内存不足，导致 PCL 无法继续运行。请在关闭一部分不需要的程序后再试。";
            }
            else if (InnerEx is COMException)
            {
                CommonReason = "由于操作系统或显卡存在问题，导致出现错误。请尝试重启 PCL。";
            }
            else if (new[] { "远程主机强迫关闭了", "远程方已关闭传输流", "未能解析此远程名称", "由于目标计算机积极拒绝", "操作已超时", "操作超时", "服务器超时", "连接超时" }.Any(s => Desc.Contains(s)))
            {
                CommonReason = "你的网络环境不佳，导致难以连接到服务器。请检查网络，多重试几次，或尝试使用 VPN。";
            }
            else if (InnerEx is PlatformNotSupportedException)
            {
                CommonReason = "你当前的 Windows 版本过低，无法运行当前版本的 PCL。请升级到 Windows 10 或更高版本后再试。";
            }

            // 构造输出信息
            if (CommonReason is not null)
            {
                return CommonReason + "详细错误：" + DescList.First();
            }
            else
            {
                DescList.Reverse(); // 让最深层错误在最左边
                return DescList.Join(" ← ");
            }
        }

