        /// <summary>
    /// 将文件大小转化为适合的文本形式，如“1.28 M”。
    /// </summary>
    /// <param name="FileSize">以字节为单位的大小表示。</param>
        public static string GetString(long FileSize)
        {
            bool IsNegative = FileSize < 0L;
            if (IsNegative)
                FileSize *= -1;
            if (FileSize < 1000L)
            {
                // B 级
                return (IsNegative ? "-" : "") + FileSize + " B";
            }
            else if (FileSize < 1024 * 1000)
            {
                // K 级
                string RoundResult = Math.Round(FileSize / 1024d).ToString();
                return (IsNegative ? "-" : "") + Math.Round(FileSize / 1024d, (int)Math.Round(MathClamp(3 - RoundResult.Length, 0d, 2d))) + " K";
            }
            else if (FileSize < 1024 * 1024 * 1000)
            {
                // M 级
                string RoundResult = Math.Round(FileSize / 1024d / 1024d).ToString();
                return (IsNegative ? "-" : "") + Math.Round(FileSize / 1024d / 1024d, (int)Math.Round(MathClamp(3 - RoundResult.Length, 0d, 2d))) + " M";
            }
            else
            {
                // G 级
                string RoundResult = Math.Round(FileSize / 1024d / 1024d / 1024d).ToString();
                return (IsNegative ? "-" : "") + Math.Round(FileSize / 1024d / 1024d / 1024d, (int)Math.Round(MathClamp(3 - RoundResult.Length, 0d, 2d))) + " G";
            }
        }

        /// <summary>
    /// 获取 JSON 对象。
    /// </summary>
        public static object GetJson(string Data)
        {
            try
            {
                return JsonConvert.DeserializeObject(Data, new JsonSerializerSettings() { DateTimeZoneHandling = DateTimeZoneHandling.Local });
            }
            catch (Exception ex)
            {
                int Length = (Data ?? "").Length;
                throw new Exception("格式化 JSON 失败：" + (Length > 2000 ? Data.Substring(0, 500) + $"...(全长 {Length} 个字符)..." + Strings.Right(Data, 500) : Data));
            }
        }

        /// <summary>
    /// 将第一个字符转换为大写，其余字符转换为小写。
    /// </summary>
        public static string Capitalize(this string word)
        {
            if (string.IsNullOrEmpty(word))
                return word;
            return word.Substring(0, 1).ToUpperInvariant() + word.Substring(1).ToLowerInvariant();
        }

        /// <summary>
    /// 将字符串统一至某个长度，过短则以 Code 将其右侧填充，过长则截取靠左的指定长度。
    /// </summary>
        public static string StrFill(string Str, string Code, byte Length)
        {
            if (Str.Length > Length)
                return Strings.Mid(Str, 1, Length);
            return Strings.Mid(Str.PadRight(Length, Conversions.ToChar(Code)), Str.Length + 1) + Str;
        }
        /// <summary>
    /// 将一个小数显示为固定的小数点后位数形式，将向零取整。
    /// 如 12 保留 2 位则输出 12.00，而 95.678 保留 2 位则输出 95.67。
    /// </summary>
        public static string StrFillNum(double Num, int Length)
        {
            string StrFillNumRet = default;
            Num = Math.Round(Num, Length, MidpointRounding.AwayFromZero);
            StrFillNumRet = Num.ToString();
            if (!StrFillNumRet.Contains("."))
                return (StrFillNumRet + ".").PadRight(StrFillNumRet.Length + 1 + Length, '0');
            return StrFillNumRet.PadRight(StrFillNumRet.Split(".")[0].Length + 1 + Length, '0');
        }
        /// <summary>
    /// 移除字符串首尾的标点符号、回车，以及括号中、冒号后的补充说明内容。
    /// </summary>
        public static object StrTrim(string Str, bool RemoveQuote = true)
        {
            if (RemoveQuote)
                Str = Str.Split("（")[0].Split("：")[0].Split("(")[0].Split(":")[0];
            return Str.Trim('.', '。', '！', ' ', '!', '?', '？', Conversions.ToChar(Constants.vbCr), Conversions.ToChar(Constants.vbLf));
        }
        /// <summary>
    /// 连接字符串。
    /// </summary>
        public static string Join(this IEnumerable List, string Split)
        {
            var Builder = new StringBuilder();
            bool IsFirst = true;
            foreach (var Element in List)
            {
                if (IsFirst)
                {
                    IsFirst = false;
                }
                else
                {
                    Builder.Append(Split);
                }
                if (Element is not null)
                    Builder.Append(Element);
            }
            return Builder.ToString();
        }
        /// <summary>
    /// 分割字符串。
    /// </summary>
        public static string[] Split(this string FullStr, string SplitStr)
        {
            if (SplitStr.Length == 1)
            {
                return FullStr.Split(SplitStr[0]);
            }
            else
            {
                return FullStr.Split(new[] { SplitStr }, StringSplitOptions.None);
            }
        }

        /// <summary>
    /// 获取字符串哈希值。
    /// </summary>
        public static ulong GetHash(string Str)
        {
            ulong GetHashRet = default;
            GetHashRet = 5381UL;
            for (int i = 0, loopTo = Str.Length - 1; i <= loopTo; i++)
                GetHashRet = GetHashRet << 5 ^ GetHashRet ^ (ulong)Strings.AscW(Str[i]);
            return GetHashRet ^ 0xA98F501BC684032FUL;
        }
        /// <summary>
    /// 获取字符串 MD5。
    /// </summary>
        public static string GetStringMD5(string Str)
        {
            var md5Hasher = new MD5CryptoServiceProvider();
            byte[] hashedDataBytes;
            hashedDataBytes = md5Hasher.ComputeHash(Encoding.GetEncoding("gb2312").GetBytes(Str));
            var tmp = new StringBuilder();
            foreach (byte i in hashedDataBytes)
                tmp.Append(i.ToString("x2"));
            return tmp.ToString();
        }
        /// <summary>
    /// 检查字符串中的字符是否均为 ASCII 字符。
    /// </summary>
        public static bool IsASCII(this string Input)
        {
            return Input.All(c => Strings.AscW(c) < 128);
        }

        /// <summary>
    /// 获取在子字符串第一次出现之前的部分，例如对 2024/11/08 拆切 / 会得到 2024。
    /// 如果未找到子字符串则不裁切。
    /// </summary>
        public static string BeforeFirst(this string Str, string Text, bool IgnoreCase = false)
        {
            int Pos = string.IsNullOrEmpty(Text) ? -1 : Str.IndexOfF(Text, IgnoreCase);
            if (Pos >= 0)
            {
                return Str.Substring(0, Pos);
            }
            else
            {
                return Str;
            }
        }
        /// <summary>
    /// 获取在子字符串最后一次出现之前的部分，例如对 2024/11/08 拆切 / 会得到 2024/11。
    /// 如果未找到子字符串则不裁切。
    /// </summary>
        public static string BeforeLast(this string Str, string Text, bool IgnoreCase = false)
        {
            int Pos = string.IsNullOrEmpty(Text) ? -1 : Str.LastIndexOfF(Text, IgnoreCase);
            if (Pos >= 0)
            {
                return Str.Substring(0, Pos);
            }
            else
            {
                return Str;
            }
        }
        /// <summary>
    /// 获取在子字符串第一次出现之后的部分，例如对 2024/11/08 拆切 / 会得到 11/08。
    /// 如果未找到子字符串则不裁切。
    /// </summary>
        public static string AfterFirst(this string Str, string Text, bool IgnoreCase = false)
        {
            int Pos = string.IsNullOrEmpty(Text) ? -1 : Str.IndexOfF(Text, IgnoreCase);
            if (Pos >= 0)
            {
                return Str.Substring(Pos + Text.Length);
            }
            else
            {
                return Str;
            }
        }
        /// <summary>
    /// 获取在子字符串最后一次出现之后的部分，例如对 2024/11/08 拆切 / 会得到 08。
    /// 如果未找到子字符串则不裁切。
    /// </summary>
        public static string AfterLast(this string Str, string Text, bool IgnoreCase = false)
        {
            int Pos = string.IsNullOrEmpty(Text) ? -1 : Str.LastIndexOfF(Text, IgnoreCase);
            if (Pos >= 0)
            {
                return Str.Substring(Pos + Text.Length);
            }
            else
            {
                return Str;
            }
        }
        /// <summary>
    /// 获取处于两个子字符串之间的部分，裁切尽可能多的内容。
    /// 等效于 AfterLast 后接 BeforeFirst。
    /// 如果未找到子字符串则不裁切。
    /// </summary>
        public static string Between(this string Str, string After, string Before, bool IgnoreCase = false)
        {
            int StartPos = string.IsNullOrEmpty(After) ? -1 : Str.LastIndexOfF(After, IgnoreCase);
            if (StartPos >= 0)
            {
                StartPos += After.Length;
            }
            else
            {
                StartPos = 0;
            }
            int EndPos = string.IsNullOrEmpty(Before) ? -1 : Str.IndexOfF(Before, StartPos, IgnoreCase);
            if (EndPos >= 0)
            {
                return Str.Substring(StartPos, EndPos - StartPos);
            }
            else if (StartPos > 0)
            {
                return Str.Substring(StartPos);
            }
            else
            {
                return Str;
            }
        }

