        /// <summary>
    /// 不会报错的 Val。
    /// 如果输入有误，返回 0。
    /// </summary>
        public static double Val(object Str)
        {
            try
            {
                return Str is string && Conversions.ToBoolean(Operators.ConditionalCompareObjectEqual(Str, "&", false)) ? 0d : Conversion.Val(Str);
            }
            catch
            {
                return 0d;
            }
        }

        // 转义
        /// <summary>
    /// 为字符串进行 XML 转义。
    /// </summary>
        public static string EscapeXML(string Str)
        {
            if (Str.StartsWithF("{"))
                Str = "{}" + Str; // #4187
            return Str.Replace("&", "&amp;").Replace("<", "&lt;").Replace(">", "&gt;").Replace("'", "&apos;").Replace("\"", "&quot;").Replace(Constants.vbCrLf, "&#xa;");
        }
        /// <summary>
    /// 为字符串进行 Like 关键字转义。
    /// </summary>
        public static string EscapeLikePattern(string input)
        {
            var sb = new StringBuilder();
            foreach (char c in input)
            {
                switch (c)
                {
                    case '[':
                    case ']':
                    case '*':
                    case '?':
                    case '#':
                        {
                            sb.Append('[').Append(c).Append(']');
                            break;
                        }

                    default:
                        {
                            sb.Append(c);
                            break;
                        }
                }
            }
            return sb.ToString();
        }

        // 正则
        /// <summary>
    /// 搜索字符串中的所有正则匹配项。
    /// </summary>
        public static List<string> RegexSearch(this string str, string regex, RegexOptions options = RegexOptions.None)
        {
            List<string> RegexSearchRet = default;
            try
            {
                RegexSearchRet = new List<string>();
                var RegexSearchRes = new Regex(regex, options).Matches(str);
                if (RegexSearchRes is null)
                    return RegexSearchRet;
                foreach (Match item in RegexSearchRes)
                    RegexSearchRet.Add(item.Value);
            }
            catch (Exception ex)
            {
                Log(ex, "正则匹配全部项出错");
                return new List<string>();
            }

            return RegexSearchRet;
        }
        /// <summary>
    /// 获取字符串中的第一个正则匹配项，若无匹配则返回 Nothing。
    /// </summary>
        public static string RegexSeek(this string str, string regex, RegexOptions options = RegexOptions.None)
        {
            try
            {
                string Result = Regex.Match(str, regex, options).Value;
                return string.IsNullOrEmpty(Result) ? null : Result;
            }
            catch (Exception ex)
            {
                Log(ex, "正则匹配第一项出错");
                return null;
            }
        }
        /// <summary>
    /// 检查字符串是否匹配某正则模式。
    /// </summary>
        public static bool RegexCheck(this string str, string regex, RegexOptions options = RegexOptions.None)
        {
            try
            {
                return Regex.IsMatch(str, regex, options);
            }
            catch (Exception ex)
            {
                Log(ex, "正则检查出错");
                return false;
            }
        }
