        /// <summary>
    /// 获取搜索文本的相似度。
    /// </summary>
    /// <param name="Source">被搜索的长内容。</param>
    /// <param name="Query">用户输入的搜索文本。</param>
        private static double SearchSimilarity(string Source, string Query)
        {
            int qp = 0;
            double lenSum = 0d;
            Source = Source.ToLower().Replace(" ", "");
            Query = Query.ToLower().Replace(" ", "");
            int sourceLength = Source.Length;
            int queryLength = Query.Length; // 用于计算最后因数的长度缓存
            while (qp < queryLength)
            {
                // 对 qp 作为开始位置计算
                int sp = 0;
                int lenMax = 0;
                int spMax = 0;
                // 查找以 qp 为头的最大子串
                while (sp < Source.Length)
                {
                    // 对每个 sp 作为开始位置计算最大子串
                    int len = 0;
                    while (qp + len < queryLength && sp + len < Source.Length && Source[sp + len] == Query[qp + len])
                        len += 1;
                    // 存储 len
                    if (len > lenMax)
                    {
                        lenMax = len;
                        spMax = sp;
                    }
                    // 根据结果增加 sp
                    sp += Math.Max(1, len);
                }
                if (lenMax > 0)
                {
                    Source = Source.Substring(0, spMax) + (Source.Count() > spMax + lenMax ? Source.Substring(spMax + lenMax) : string.Empty); // 将源中的对应字段替换空
                                                                                                                                               // 存储 lenSum
                    double IncWeight = Math.Pow(1.4d, 3 + lenMax) - 3.6d; // 根据长度加成
                    IncWeight *= 1d + 0.3d * Math.Max(0, 3 - Math.Abs(qp - spMax)); // 根据位置加成
                    lenSum += IncWeight;
                }
                // 根据结果增加 qp
                qp += Math.Max(1, lenMax);
            }
            // 计算结果：重复字段量 × 源长度影响比例
            return lenSum / queryLength * (3d / Math.Pow(sourceLength + 15, 0.5d)) * (queryLength <= 2 ? 3 - queryLength : 1);
        }
        /// <summary>
    /// 获取多段文本加权后的相似度。
    /// </summary>
        private static double SearchSimilarityWeighted(List<KeyValuePair<string, double>> Source, string Query)
        {
            double TotalWeight = 0d;
            double Sum = 0d;
            foreach (var Pair in Source)
            {
                Sum += SearchSimilarity(Pair.Key, Query) * Pair.Value;
                TotalWeight += Pair.Value;
            }
            return Sum / TotalWeight;
        }
        /// <summary>
    /// 用于搜索的项目。
    /// </summary>
        public class SearchEntry<T>
        {
            /// <summary>
        /// 该项目对应的源数据。
        /// </summary>
            public T Item;
            /// <summary>
        /// 该项目用于搜索的源。
        /// </summary>
            public List<KeyValuePair<string, double>> SearchSource;
            /// <summary>
        /// 相似度。
        /// </summary>
            public double Similarity;
            /// <summary>
        /// 是否完全匹配。
        /// </summary>
            public bool AbsoluteRight;
        }
        /// <summary>
    /// 进行多段文本加权搜索，获取相似度较高的数项结果。
    /// </summary>
    /// <param name="MaxBlurCount">返回的最大模糊结果数。</param>
    /// <param name="MinBlurSimilarity">返回结果要求的最低相似度。</param>
        public static List<SearchEntry<T>> Search<T>(List<SearchEntry<T>> Entries, string Query, int MaxBlurCount = 5, double MinBlurSimilarity = 0.1d)
        {
            // 初始化
            var ResultList = new List<SearchEntry<T>>();
            if (!Entries.Any())
                return ResultList;
            // 进行搜索，获取相似信息
            foreach (var Entry in Entries)
            {
                Entry.Similarity = SearchSimilarityWeighted(Entry.SearchSource, Query);
                Entry.AbsoluteRight = Query.Split(" ").All(QueryPart => Entry.SearchSource.Any(Source => Source.Key.Replace(" ", "").ContainsF(QueryPart, true))); // 对于按空格分割的每一段
                                                                                                                                                                   // 若与任意一个搜索源完全匹配，则标记为完全匹配项
            }
            // 按照相似度进行排序
            Entries = Entries.Sort((Left, Right) => { if (Left.AbsoluteRight ^ Right.AbsoluteRight) { return Left.AbsoluteRight; } else { return Left.Similarity > Right.Similarity; } });
            // 返回结果
            int BlurCount = 0;
            foreach (var Entry in Entries)
            {
                if (Entry.AbsoluteRight)
                {
                    ResultList.Add(Entry); // 完全匹配，直接加入
                }
                else
                {
                    if (Entry.Similarity < MinBlurSimilarity || BlurCount == MaxBlurCount)
                        break; // 模糊结果边界条件
                    ResultList.Add(Entry);
                    BlurCount += 1;
                } // 模糊结果计数
            }
            return ResultList;
        }

