        /// <summary>
    /// 线程安全的，可以直接使用 For Each 的 List。
    /// 在使用 For Each 循环时，列表的结果可能并非最新，但不会抛出异常。
    /// </summary>
        public class SafeList<T> : SynchronizedCollection<T>, IEnumerable, IEnumerable<T>
        {
            // 构造函数
            public SafeList() : base()
            {
            }
            public SafeList(IEnumerable<T> Data) : base(new object(), Data)
            {
            }
            public static implicit operator SafeList<T>(List<T> Data)
            {
                return new SafeList<T>(Data);
            }
            public static implicit operator List<T>(SafeList<T> Data)
            {
                return new List<T>(Data);
            }
            // 基于 SyncLock 覆写
            public new IEnumerator<T> GetEnumerator()
            {
                lock (SyncRoot)
                    return Items.ToList().GetEnumerator();
            }
            private IEnumerator GetEnumeratorGeneral()
            {
                lock (SyncRoot)
                    return Items.ToList().GetEnumerator();
            }

            IEnumerator IEnumerable.GetEnumerator() => GetEnumeratorGeneral();
        }

        /// <summary>
    /// 线程安全的，可以直接使用 For Each 的字典。
    /// 在使用 For Each 循环时，字典的结果可能并非最新，但不会抛出异常。
    /// </summary>
        public class SafeDictionary<TKey, TValue> : IDictionary<TKey, TValue>, IEnumerable<KeyValuePair<TKey, TValue>>
        {

            private readonly object SyncRoot = new object();
            private readonly Dictionary<TKey, TValue> _Dictionary = new Dictionary<TKey, TValue>();

            // 构造函数
            public SafeDictionary()
            {
            }
            public SafeDictionary(IEnumerable<KeyValuePair<TKey, TValue>> data)
            {
                foreach (var DataItem in data)
                    _Dictionary.Add(DataItem.Key, DataItem.Value);
            }

            // 线程安全的方法实现
            public void Add(TKey key, TValue value)
            {
                lock (SyncRoot)
                    _Dictionary.Add(key, value);
            }
            public bool ContainsKey(TKey key)
            {
                lock (SyncRoot)
                    return _Dictionary.ContainsKey(key);
            }
            public ICollection<TKey> Keys
            {
                get
                {
                    lock (SyncRoot)
                        return new List<TKey>(_Dictionary.Keys);
                }
            }
            public bool Remove(TKey key)
            {
                lock (SyncRoot)
                    return _Dictionary.Remove(key);
            }
            public bool TryGetValue(TKey key, out TValue value)
            {
                lock (SyncRoot)
                    return _Dictionary.TryGetValue(key, out value);
            }
            public ICollection<TValue> Values
            {
                get
                {
                    lock (SyncRoot)
                        return new List<TValue>(_Dictionary.Values);
                }
            }
            public TValue this[TKey key]
            {
                get
                {
                    lock (SyncRoot)
                        return _Dictionary[key];
                }
                set
                {
                    lock (SyncRoot)
                        _Dictionary[key] = value;
                }
            }
            public void Add(KeyValuePair<TKey, TValue> item)
            {
                lock (SyncRoot)
                    _Dictionary.Add(item.Key, item.Value);
            }
            public void Clear()
            {
                lock (SyncRoot)
                    _Dictionary.Clear();
            }
            public bool Contains(KeyValuePair<TKey, TValue> item)
            {
                lock (SyncRoot)
                    return ((IDictionary<TKey, TValue>)_Dictionary).Contains(item);
            }
            public void CopyTo(KeyValuePair<TKey, TValue>[] array, int arrayIndex)
            {
                lock (SyncRoot)
                    ((IDictionary<TKey, TValue>)_Dictionary).CopyTo(array, arrayIndex);
            }
            public int Count
            {
                get
                {
                    lock (SyncRoot)
                        return _Dictionary.Count;
                }
            }
            public bool IsReadOnly
            {
                get
                {
                    return false;
                }
            }
            public bool Remove(KeyValuePair<TKey, TValue> item)
            {
                lock (SyncRoot)
                    return ((IDictionary<TKey, TValue>)_Dictionary).Remove(item);
            }

            // 枚举器
            public IEnumerator<KeyValuePair<TKey, TValue>> GetEnumerator()
            {
                lock (SyncRoot)
                    return new List<KeyValuePair<TKey, TValue>>(_Dictionary).GetEnumerator();
            }
            private IEnumerator GetEnumeratorGeneral()
            {
                return GetEnumerator();
            }

            IEnumerator IEnumerable.GetEnumerator() => GetEnumeratorGeneral();
        }

