        /// <summary>
    /// 将时间间隔转换为类似“5 分 10 秒前”的易于阅读的形式。
    /// </summary>
        public static string GetTimeSpanString(TimeSpan Span, bool IsShortForm)
        {
            string GetTimeSpanStringRet = default;
            string EndFix = Span.TotalMilliseconds > 0d ? "后" : "前";
            if (Span.TotalMilliseconds < 0d)
                Span = -Span;
            double TotalMonthes = Math.Floor(Span.Days / 30d);
            if (IsShortForm)
            {
                if (TotalMonthes >= 12d)
                {
                    // 1+ 年，“3 年”
                    GetTimeSpanStringRet = Math.Floor(TotalMonthes / 12d) + " 年";
                }
                else if (TotalMonthes >= 2d)
                {
                    // 2~11 月，“5 个月”
                    GetTimeSpanStringRet = TotalMonthes + " 个月";
                }
                else if (Span.TotalDays >= 2d)
                {
                    // 2 天 ~ 2 月，“23 天”
                    GetTimeSpanStringRet = Span.Days + " 天";
                }
                else if (Span.TotalHours >= 1d)
                {
                    // 1 小时 ~ 2 天，“15 小时”
                    GetTimeSpanStringRet = Span.Hours + " 小时";
                }
                else if (Span.TotalMinutes >= 1d)
                {
                    // 1 分钟 ~ 1 小时，“49 分钟”
                    GetTimeSpanStringRet = Span.Minutes + " 分钟";
                }
                else if (Span.TotalSeconds >= 1d)
                {
                    // 1 秒 ~ 1 分钟，“23 秒”
                    GetTimeSpanStringRet = Span.Seconds + " 秒";
                }
                else
                {
                    // 不到 1 秒
                    GetTimeSpanStringRet = "1 秒";
                }
            }
            else if (TotalMonthes >= 61d)
            {
                // 5+ 年，“5 年”
                GetTimeSpanStringRet = Math.Floor(TotalMonthes / 12d) + " 年";
            }
            else if (TotalMonthes >= 12d)
            {
                // 12~60 月，“1 年 2 个月”
                GetTimeSpanStringRet = Math.Floor(TotalMonthes / 12d) + " 年" + (TotalMonthes % 12d > 0d ? " " + TotalMonthes % 12d + " 个月" : "");
            }
            else if (TotalMonthes >= 4d)
            {
                // 4~11 月，“5 个月”
                GetTimeSpanStringRet = TotalMonthes + " 个月";
            }
            else if (TotalMonthes >= 1d)
            {
                // 1~4 月，“2 个月 13 天”
                GetTimeSpanStringRet = TotalMonthes + " 月" + (Span.Days % 30 > 0 ? " " + Span.Days % 30 + " 天" : "");
            }
            else if (Span.TotalDays >= 4d)
            {
                // 4~30 天，“23 天”
                GetTimeSpanStringRet = Span.Days + " 天";
            }
            else if (Span.TotalDays >= 1d)
            {
                // 1~3 天，“2 天 20 小时”
                GetTimeSpanStringRet = Span.Days + " 天" + (Span.Hours > 0 ? " " + Span.Hours + " 小时" : "");
            }
            else if (Span.TotalHours >= 10d)
            {
                // 10 小时 ~ 1 天，“15 小时”
                GetTimeSpanStringRet = Span.Hours + " 小时";
            }
            else if (Span.TotalHours >= 1d)
            {
                // 1~10 小时，“1 小时 20 分钟”
                GetTimeSpanStringRet = Span.Hours + " 小时" + (Span.Minutes > 0 ? " " + Span.Minutes + " 分钟" : "");
            }
            else if (Span.TotalMinutes >= 10d)
            {
                // 10 分钟 ~ 1 小时，“49 分钟”
                GetTimeSpanStringRet = Span.Minutes + " 分钟";
            }
            else if (Span.TotalMinutes >= 1d)
            {
                // 1~10 分钟，“9 分 23 秒”
                GetTimeSpanStringRet = Span.Minutes + " 分" + (Span.Seconds > 0 ? " " + Span.Seconds + " 秒" : "");
            }
            else if (Span.TotalSeconds >= 1d)
            {
                // 1 秒 ~ 1 分钟，“23 秒”
                GetTimeSpanStringRet = Span.Seconds + " 秒";
            }
            else
            {
                // 不到 1 秒
                GetTimeSpanStringRet = "1 秒";
            }
            GetTimeSpanStringRet += EndFix;
            return GetTimeSpanStringRet;
        }
