        /// <summary>
    /// 尝试从字典中获取某项，如果该项不存在，则返回默认值。
    /// </summary>
        public static TValue GetOrDefault<TKey, TValue>(this Dictionary<TKey, TValue> Dict, TKey Key, TValue DefaultValue = default)
        {
            if (Dict.ContainsKey(Key))
            {
                return Dict[Key];
            }
            else
            {
                return DefaultValue;
            }
        }
        /// <summary>
    /// 将某项添加到以列表作为值的字典中。
    /// </summary>
        public static void AddToList<TKey, TValue>(this Dictionary<TKey, List<TValue>> Dict, TKey Key, TValue Value)
        {
            if (Dict.ContainsKey(Key))
            {
                Dict[Key].Add(Value);
            }
            else
            {
                Dict.Add(Key, new List<TValue>() { Value });
            }
        }

        /// <summary>
    /// 获取程序启动参数。
    /// </summary>
    /// <param name="Name">参数名。</param>
    /// <param name="DefaultValue">默认值。</param>
        public static object GetProgramArgument(string Name, object DefaultValue = null)
        {
            if (DefaultValue is null) DefaultValue = "";
            string[] AllArguments = Interaction.Command().Split(" ");
            for (int i = 0, loopTo = AllArguments.Length - 1; i <= loopTo; i++)
            {
                if ((AllArguments[i] ?? "") == ("-" + Name ?? ""))
                {
                    if (AllArguments.Length == i + 1 || AllArguments[i + 1].StartsWithF("-"))
                        return true;
                    return AllArguments[i + 1];
                }
            }
            return DefaultValue;
        }

        /// <summary>
    /// 时间戳转化为日期。
    /// </summary>
        public static DateTime GetDate(int timeStamp)
        {
            var dtStart = TimeZone.CurrentTimeZone.ToLocalTime(new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc));
            long lTime = timeStamp * 10000000L;
            return dtStart.Add(new TimeSpan(lTime));
        }
        /// <summary>
    /// 将 UTC 时间转化为当前时区的时间。
    /// </summary>
        public static DateTime GetLocalTime(DateTime UtcDate)
        {
            return DateTime.SpecifyKind(UtcDate, DateTimeKind.Utc).ToLocalTime();
        }

        /// <summary>
    /// 打开网页。
    /// </summary>
        public static void OpenWebsite(string Url)
        {
            try
            {
                if (!Url.StartsWithF("http", true) && !Url.StartsWithF("minecraft://", true))
                {
                    throw new Exception(Url + " 不是一个有效的网址，它必须以 http 开头！");
                }
                Log("[System] 正在打开网页：" + Url);
                Process.Start(Url);
            }
            catch (Exception ex)
            {
                Log(ex, "无法打开网页（" + Url + "）");
                ClipboardSet(Url, false);
                ModMain.MyMsgBox("可能由于浏览器未正确配置，PCL 无法为你打开网页。" + Constants.vbCrLf + "网址已经复制到剪贴板，若有需要可以手动粘贴访问。" + Constants.vbCrLf + $"网址：{Url}", "无法打开网页");
            }
        }
