        // UI 截图
        /// <summary>
    /// 将某个控件的呈现转换为图片。
    /// </summary>
        public static ImageBrush ControlBrush(FrameworkElement UI)
        {
            double Width = UI.ActualWidth;
            double Height = UI.ActualHeight;
            if (Width < 1d || Height < 1d)
                return new ImageBrush();
            var bmp = new RenderTargetBitmap((int)Math.Round(GetPixelSize(Width)), (int)Math.Round(GetPixelSize(Height)), DPI, DPI, PixelFormats.Pbgra32);
            bmp.Render(UI);
            return new ImageBrush(bmp);
        }
        /// <summary>
    /// 将某个控件的模拟呈现转换为图片。
    /// </summary>
        public static ImageBrush ControlBrush(FrameworkElement UI, double Width, double Height, double Left = 0d, double Top = 0d)
        {
            UI.Measure(new Size(Width, Height));
            UI.Arrange(new Rect(0d, 0d, Width, Height));
            var bmp = new RenderTargetBitmap((int)Math.Round(GetPixelSize(Width)), (int)Math.Round(GetPixelSize(Height)), DPI, DPI, PixelFormats.Default);
            bmp.Render(UI);
            if (!(Left == 0d && Top == 0d))
                UI.Arrange(new Rect(Left, Top, Width, Height));
            return new ImageBrush(bmp);
        }
