        /// <summary>
    /// 检查某个控件是否位于主窗口可视区域内，且控件本身可见。
    /// </summary>
        public static bool IsVisibleInForm(this FrameworkElement element)
        {
            if (!element.IsVisible)
                return false;
            var bounds = element.TransformToAncestor(ModMain.FrmMain).TransformBounds(new Rect(0d, 0d, element.ActualWidth, element.ActualHeight));
            var rect = new Rect(0d, 0d, ModMain.FrmMain.ActualWidth, ModMain.FrmMain.ActualHeight);
            return rect.Contains(bounds.TopLeft) || rect.Contains(bounds.BottomRight);
        }

        /// <summary>
    /// 控件是否受到 TextTrimming 属性影响，导致内容被截取。
    /// </summary>
        public static bool IsTextTrimmed(this TextBlock Control)
        {
            Control.Measure(new Size(double.MaxValue, double.MaxValue));
            return Control.DesiredSize.Width > Control.ActualWidth;
        }

        /// <summary>
    /// 获取系统是否是深色模式。
    /// </summary>
    /// <returns></returns>
        public static bool IsSystemInDarkMode()
        {
            var RegistryKey = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize");
            if (RegistryKey is null)
                return false;
            var Value = RegistryKey.GetValue("AppsUseLightTheme");
            return Value is not null && Value.ToString() == "0";
        }

        /// <summary>
    /// 获取文本在被渲染后的宽度。
    /// </summary>
        public static double MeasureStringWidth(string text, double fontSize = 14d, FontFamily fontFamily = null)
        {
            if (fontFamily is null)
                fontFamily = new FontFamily("微软雅黑");
            var formattedText = new FormattedText(text, CultureInfo.CurrentCulture, FlowDirection.LeftToRight, new Typeface(fontFamily, FontStyles.Normal, FontWeights.Normal, FontStretches.Normal), fontSize, Brushes.Black, new NumberSubstitution(), TextFormattingMode.Display, new DpiScale(1d, 1d).PixelsPerDip);
            return formattedText.Width;
        }

