        private static StringBuilder LogList = new StringBuilder();
        private static StreamWriter LogWritter;
        public static void LogStart()
        {
            RunInNewThread(() =>
        {
            bool IsInitSuccess = true;
            try
            {
                for (int i = 4; i >= 1; i -= 1)
                {
                    if (File.Exists(Path + @"PCL\Log-CE" + i + ".log"))
                    {
                        if (File.Exists(Path + @"PCL\Log-CE" + (i + 1) + ".log"))
                            File.Delete(Path + @"PCL\Log-CE" + (i + 1) + ".log");
                        CopyFile(Path + @"PCL\Log-CE" + i + ".log", Path + @"PCL\Log-CE" + (i + 1) + ".log");
                    }
                }
                File.Create(Path + @"PCL\Log-CE1.log").Dispose();
            }
            catch (IOException ex)
            {
                IsInitSuccess = false;
                ModMain.Hint("可能同时开启了多个 PCL，程序可能会出现未知问题！", ModMain.HintType.Critical);
                Log(ex, "日志初始化失败（疑似文件占用问题）");
            }
            catch (Exception ex)
            {
                IsInitSuccess = false;
                Log(ex, "日志初始化失败", LogLevel.Hint);
            }
            try
            {
                LogWritter = new StreamWriter(Path + @"PCL\Log-CE1.log", true) { AutoFlush = true };
            }
            catch (Exception ex)
            {
                LogWritter = null;
                Log(ex, "日志写入失败", LogLevel.Hint);
            }
            while (true)
            {
                if (IsInitSuccess)
                {
                    LogFlush();
                }
                else
                {
                    LogList = new StringBuilder();
                } // 清空 LogList 避免内存爆炸
                Thread.Sleep(50);
            }
        }, "Log Writer", ThreadPriority.Lowest);
        }
        private readonly static object LogFlushLock = new object(); // 防止外部调用 LogFlush 时同时输出多次日志
        public static void LogFlush()
        {
            if (LogWritter is null)
                return;
            string Log = null;
            lock (LogFlushLock)
            {
                if (LogList.Length > 0)
                {
                    StringBuilder LogListCache;
                    LogListCache = LogList;
                    LogList = new StringBuilder();
                    Log = LogListCache.ToString();
                }
            }
            if (Log is not null)
            {
                LogWritter.Write(Log);
            }
        }

        private readonly static object LogListLock = new object(); // 防止日志乱码，只在调试模式下启用
                                                                   /// <summary>
