    /// <param name="Title">如果要求弹窗，指定弹窗的标题。</param>
        public static void Log(string Text, LogLevel Level = LogLevel.Normal, string Title = "出现错误")
        {
            string AppendText = "[" + GetTimeNow() + "] " + Text + Constants.vbCrLf; // 减轻同步锁占用
            if (ModeDebug)
            {
                lock (LogListLock)
                    LogList.Append(AppendText);
            }
            else
            {
                LogList.Append(AppendText);
            }
            /* TODO ERROR: Skipped IfDirectiveTrivia
            #If DEBUG Then
            *//* TODO ERROR: Skipped DisabledTextTrivia
                    Console.Write(AppendText)
            *//* TODO ERROR: Skipped EndIfDirectiveTrivia
            #End If
            */
            if (IsProgramEnded || Level == LogLevel.Normal)
                return;

            // 去除前缀
            Text = Text.RegexReplace(@"\[[^\]]+?\] ", "");

            // 输出提示
            switch (Level)
            {
                /* TODO ERROR: Skipped IfDirectiveTrivia
                #If DEBUG Then
                *//* TODO ERROR: Skipped DisabledTextTrivia
                            Case LogLevel.Developer
                                Hint("[开发者模式] " & Text, HintType.Info, False)
                            Case LogLevel.Debug
                                Hint("[调试模式] " & Text, HintType.Info, False)
                *//* TODO ERROR: Skipped ElseDirectiveTrivia
                #Else
                */
                case LogLevel.Developer:
                    {
                        break;
                    }
                case LogLevel.Debug:
                    {
                        if (ModeDebug)
                            ModMain.Hint("[调试模式] " + Text, ModMain.HintType.Info, false);
                        break;
                    }
                /* TODO ERROR: Skipped EndIfDirectiveTrivia
                #End If
                */
                case LogLevel.Hint:
                    {
                        ModMain.Hint(Text, ModMain.HintType.Critical, false);
                        break;
                    }
                case LogLevel.Msgbox:
                    {
                        ModMain.MyMsgBox(Text, Title, IsWarn: true);
                        break;
                    }
                case LogLevel.Feedback:
                    {
                        if (CanFeedback(false))
                        {
                            if (ModMain.MyMsgBox(Text + Constants.vbCrLf + Constants.vbCrLf + "是否反馈此问题？如果不反馈，这个问题可能永远无法得到解决！", Title, "反馈", "取消", IsWarn: true) == 1)
                                Feedback(false, true);
                        }
                        else
                        {
                            ModMain.MyMsgBox(Text + Constants.vbCrLf + Constants.vbCrLf + "将 PCL 更新至最新版或许可以解决这个问题……", Title, IsWarn: true);
                        }

                        break;
                    }
                case LogLevel.Assert:
                    {
                        long Time = GetTimeTick();
                        if (CanFeedback(false))
                        {
                            if (Interaction.MsgBox(Text + Constants.vbCrLf + Constants.vbCrLf + "是否反馈此问题？如果不反馈，这个问题可能永远无法得到解决！", (MsgBoxStyle)((int)MsgBoxStyle.Critical + (int)MsgBoxStyle.YesNo), Title) == MsgBoxResult.Yes)
                                Feedback(false, true);
                        }
                        else
                        {
                            Interaction.MsgBox(Text + Constants.vbCrLf + Constants.vbCrLf + "将 PCL 更新至最新版或许可以解决这个问题……", MsgBoxStyle.Critical, Title);
                        }
                        if (GetTimeTick() - Time < 1500L)
                        {
                            // 弹窗无法保留
                            Log("[System] PCL 已崩溃：" + Constants.vbCrLf + Text);
                            FormMain.EndProgramForce(ProcessReturnValues.Exception);
                        }
                        else
                        {
                            FormMain.EndProgramForce(ProcessReturnValues.Fail);
                        }

                        break;
                    }
            }

        }
