        // 获取当前的堆栈信息
        public static string GetStackTrace()
        {
            var Stack = new StackTrace();
            return Stack.GetFrames().Skip(1).Select(f => f.GetMethod()).Select(f => f.Name + "(" + f.GetParameters().Select(p => p.ToString()).ToList().Join(", ") + ") - " + f.Module.ToString()).ToList().Join(Constants.vbCrLf).Replace(Constants.vbCrLf + Constants.vbCrLf, Constants.vbCrLf);
        }

