        #region 随机

        private readonly static Random Random = new Random();

        /// <summary>
    /// 随机选择其一。
    /// </summary>
        public static T RandomOne<T>(ICollection<T> objects)
        {
            return objects.ElementAtOrDefault(RandomInteger(0, objects.Count - 1));
        }

        /// <summary>
    /// 取随机整数。
    /// </summary>
        public static int RandomInteger(int min, int max)
        {
            return (int)Math.Round(Math.Floor((max - min + 1) * Random.NextDouble()) + min);
        }

        /// <summary>
    /// 将数组随机打乱。
    /// </summary>
        public static IList<T> Shuffle<T>(IList<T> array)
        {
            IList<T> ShuffleRet = default;
            ShuffleRet = new List<T>();
            while (array.Any())
            {
                int i = RandomInteger(0, array.Count - 1);
                ShuffleRet.Add(array[i]);
                array.RemoveAt(i);
            }

            return ShuffleRet;
        }

        #endregion

