    #region WPF

    /// <summary>
/// 对数据绑定进行加法运算，使用参数决定加数。
/// </summary>
    public class AdditionConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return 0;
            double before;
            if (!double.TryParse(value.ToString(), out before))
                return 0;
            double scale = 1d;
            if (parameter is not null)
                double.TryParse(parameter.ToString(), out scale);
            return before + scale;
        }
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return Binding.DoNothing;
            double before;
            if (!double.TryParse(value.ToString(), out before))
                return Binding.DoNothing;
            double scale = 1d;
            if (parameter is not null)
                double.TryParse(parameter.ToString(), out scale);
            if (scale == 0d)
                return Binding.DoNothing;
            return before - scale;
        }
    }

    /// <summary>
/// 对数据绑定进行乘法运算，使用参数决定乘数。
/// </summary>
    public class MultiplicationConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return 0;
            double before;
            if (!double.TryParse(value.ToString(), out before))
                return 0;
            double scale = 1d;
            if (parameter is not null)
                double.TryParse(parameter.ToString(), out scale);
            return before * scale;
        }
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return Binding.DoNothing;
            double before;
            if (!double.TryParse(value.ToString(), out before))
                return Binding.DoNothing;
            double scale = 1d;
            if (parameter is not null)
                double.TryParse(parameter.ToString(), out scale);
            if (scale == 0d)
                return Binding.DoNothing;
            return before / scale;
        }
    }

    /// <summary>
/// 将取反的 Boolean 绑定到 Visibility。
/// </summary>
    public class InverseBooleanToVisibilityConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return Visibility.Visible;
            bool boolValue;
            return bool.TryParse(value.ToString(), out boolValue) ? boolValue ? Visibility.Collapsed : Visibility.Visible : Visibility.Visible;
        }
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return false;
            return value is Visibility ? Operators.ConditionalCompareObjectNotEqual(value, Visibility.Visible, false) : false;
        }
    }

    /// <summary>
/// 将 Boolean 取反。
/// </summary>
    public class InverseBooleanConverter : IValueConverter
    {
        public object Convert(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return false;
            bool boolValue;
            return bool.TryParse(value.ToString(), out boolValue) ? !boolValue : false;
        }
        public object ConvertBack(object value, Type targetType, object parameter, CultureInfo culture)
        {
            if (value is null)
                return false;
            bool localTryParse() { bool argresult = Conversions.ToBoolean(value); var ret = bool.TryParse(value.ToString(), out argresult); value = argresult; return ret; }

            return localTryParse() ? !(bool)value : false;
        }
    }
